Title: Prevent Sequelize from outputting SQL to the console on execution of query?.
Body: <p>I have a function to retrieve a user's profile.</p>

<pre><code>app.get('/api/user/profile', function (request, response)
{
  // Create the default error container
  var error = new Error();

  var User = db.User;
  User.find({
    where: { emailAddress: request.user.username}
  }).then(function(user)
  {
    if(!user)
    {
      error.status = 500; error.message = "ERROR_INVALID_USER"; error.code = 301;
      return next(error);
    }

    // Build the profile from the user object
    profile = {
      "firstName": user.firstName,
      "lastName": user.lastName,
      "emailAddress": user.emailAddress
    }
    response.status(200).send(profile);
  });
});
</code></pre>

<p>When the "find" function is called it displays the select statement on the console where the server was started. </p>

<pre><code>Executing (default): SELECT `id`, `firstName`, `lastName`, `emailAddress`, `password`, `passwordRecoveryToken`, `passwordRecoveryTokenExpire`, `createdAt`, `updatedAt` FROM `Users` AS `User` WHERE `User`.`emailAddress` = 'johndoe@doe.com' LIMIT 1;
</code></pre>

<p>Is there a way to get this not to be display?  Some flag that I set in a config file somewhere?</p>

Title: How to update a record using sequelize for node?.
Body: <p>I'm creating a RESTful API with NodeJS, express, express-resource, and Sequelize that is used to manage datasets stored in a MySQL database.</p>

<p>I'm trying to figure out how to properly update a record using Sequelize.</p>

<p>I create a model:</p>

<pre><code>module.exports = function (sequelize, DataTypes) {
  return sequelize.define('Locale', {
    id: {
      type: DataTypes.INTEGER,
      autoIncrement: true,
      primaryKey: true
    },
    locale: {
      type: DataTypes.STRING,
      allowNull: false,
      unique: true,
      validate: {
        len: 2
      }
    },
    visible: {
      type: DataTypes.BOOLEAN,
      defaultValue: 1
    }
  })
}
</code></pre>

<p>Then, in my resource controller, I define an update action.</p>

<p>In here I want to be able to update the record where the id matches a <code>req.params</code> variable.</p>

<p>First I build a model and then I use the <code>updateAttributes</code> method to update the record.</p>

<pre><code>const Sequelize = require('sequelize')
const { dbconfig } = require('../config.js')

// Initialize database connection
const sequelize = new Sequelize(dbconfig.database, dbconfig.username, dbconfig.password)

// Locale model
const Locales = sequelize.import(__dirname + './models/Locale')

// Create schema if necessary
Locales.sync()


/**
 * PUT /locale/:id
 */

exports.update = function (req, res) {
  if (req.body.name) {
    const loc = Locales.build()

    loc.updateAttributes({
      locale: req.body.name
    })
      .on('success', id =&gt; {
        res.json({
          success: true
        }, 200)
      })
      .on('failure', error =&gt; {
        throw new Error(error)
      })
  }
  else
    throw new Error('Data not provided')
}
</code></pre>

<p>Now, this does not actually produce an update query as I would expect.</p>

<p>Instead, an insert query is executed:</p>

<pre><code>INSERT INTO `Locales`(`id`, `locale`, `createdAt`, `updatedAt`, `visible`)
