Title: What does the &quot;expand&quot; option do in grunt-contrib-copy? The examples all use it but the docs say nothing about what it does.
Body: <ol>
<li>Here is the README and examples: <a href="https://github.com/gruntjs/grunt-contrib-copy/blob/master/README.md">https://github.com/gruntjs/grunt-contrib-copy/blob/master/README.md</a>.</li>
<li>Here is the relevant part of the code (that I apparently cannot understand) from <a href="https://github.com/gruntjs/grunt-contrib-copy/blob/master/tasks/copy.js">https://github.com/gruntjs/grunt-contrib-copy/blob/master/tasks/copy.js</a>:</li>
</ol>

<pre>
module.exports = function(grunt) {
  'use strict';

  var path = require('path');

  grunt.registerMultiTask('copy', 'Copy files.', function() {
    var kindOf = grunt.util.kindOf;

    var options = this.options({
      processContent: false,
      processContentExclude: []
    });

    var copyOptions = {
      process: options.processContent,
      noProcess: options.processContentExclude
    };

    grunt.verbose.writeflags(options, 'Options');

    var dest;
    var isExpandedPair;
    var tally = {
      dirs: 0,
      files: 0
    };

    this.files.forEach(function(filePair) {
      isExpandedPair = filePair.orig.expand || false;

      filePair.src.forEach(function(src) {
        if (detectDestType(filePair.dest) === 'directory') {
          dest = (isExpandedPair) ? filePair.dest : unixifyPath(path.join(filePair.dest, src));
        } else {
          dest = filePair.dest;
        }

        if (grunt.file.isDir(src)) {
          grunt.verbose.writeln('Creating ' + dest.cyan);
          grunt.file.mkdir(dest);
          tally.dirs++;
        } else {
          grunt.verbose.writeln('Copying ' + src.cyan + ' -> ' + dest.cyan);
          grunt.file.copy(src, dest, copyOptions);
          tally.files++;
        }
      });
    });
</pre>

Title: How to concatenate and minify multiple CSS and JavaScript files with Grunt.js (0.3.x).
Body: <p><em>Note: This question is only relevant for Grunt 0.3.x and has been left for reference. For help with the latest Grunt 1.x release please see my comment below this question.</em></p>

<p>I'm currently trying to use Grunt.js to setup an automatic build process for first concatenating and then minifying CSS and JavaScript files.</p>

