</blockquote>
<p><code>propTypes</code> was defined but eslint does not recognize it.</p>
<pre><code>import React, { Component, PropTypes } from 'react';

class IxClickOut extends Component {
  static propTypes = {
    children: PropTypes.any,
    onClickOut: PropTypes.func,
  };

 componentDidMount() {
    document.getElementById('app')
      .addEventListener('click', this.handleClick);
  }

  componentWillUnmount() {
    document.getElementById('app')
      .removeEventListener('click', this.handleClick);
  }

  handleClick = ({ target }: { target: EventTarget }) =&gt; {
    if (!this.containerRef.contains(target)) {
      this.props.onClickOut();
    }
  };

  containerRef: HTMLElement;

  render() {
    const { children, ...rest } = this.props;
    const filteredProps = _.omit(rest, 'onClickOut');

    return (
      &lt;div
        {...filteredProps}
        ref={container =&gt; {
          this.containerRef = container;
        }}
      &gt;
        {children}
      &lt;/div&gt;
    );
  }
}

export default IxClickOut;
</code></pre>
