    &quot;removeComments&quot;: false,
    &quot;noImplicitAny&quot;: false
  },
  &quot;exclude&quot;: [
    &quot;node_modules&quot;
  ]
}
</code></pre>
<p>My gulpfile.js:</p>
<pre><code>var gulp = require('gulp'),
    ts = require('gulp-typescript'),
    uglify = require('gulp-uglify'),
    sourcemaps = require('gulp-sourcemaps'),
    tsPath = 'app/**/*.ts';

gulp.task('ts', function () {
    var tscConfig = require('./tsconfig.json');

    gulp.src([tsPath])
        .pipe(sourcemaps.init())
        .pipe(ts(tscConfig.compilerOptions))
        .pipe(sourcemaps.write('./../js'));
});

gulp.task('watch', function() {
    gulp.watch([tsPath], ['ts']);
});

gulp.task('default', ['ts', 'watch']);
</code></pre>
<p>If I understood correctly, moduleResolution:'node' in my tsconfig should point the import statements to the node_modules folder, where lodash and lodash-es are installed. I've also tried lots of different ways to import: absolute paths, relative paths, but nothing seems to work. Any ideas?</p>
<p>If necessary I can provide a small zip file to illustrate the problem.</p>

