<pre><code>&lt;List&gt;
    {{#each items as item}}
        &lt;li&gt;&lt;a&gt;{{item}}&lt;/a&gt;&lt;/li&gt;
    {{/each}}
&lt;/List&gt;

&lt;script&gt;
    import List from './List.html'

    export default {
        components: {
            List
        }
    }
&lt;/script&gt;
</code></pre>
<p><em>List.html</em>:</p>
<pre><code>&lt;h1&gt;A Special List&lt;/h1&gt;
&lt;ul&gt;
    &lt;li&gt;&lt;a&gt;Let's all be red!&lt;/a&gt;&lt;/li&gt;
